#!/usr/bin/env node
/**
 * serve-with-free-port.js
 *
 * OPTIONAL helper. The standalone compare.html generated by riff-capture.js
 * works under file:// — no server needed. This script is only useful if you
 * want to edit variants live and refresh in the browser without re-running
 * the capture step.
 *
 * Walks up from port 3000 to find the first free port, then runs `npx serve`
 * on it. Solves the original Slack complaint: collision with Next.js / Vite
 * dev servers that hardcode 3000.
 *
 * Usage: node serve-with-free-port.js
 */

const net = require('net');
const { spawn } = require('child_process');

const START_PORT = 3000;
const MAX_TRIES = 50;

function isPortFree(port) {
  return new Promise(resolve => {
    const server = net.createServer();
    server.once('error', () => resolve(false));
    server.once('listening', () => {
      server.close(() => resolve(true));
    });
    server.listen(port, '127.0.0.1');
  });
}

async function findPort() {
  for (let i = 0; i < MAX_TRIES; i++) {
    const port = START_PORT + i;
    if (await isPortFree(port)) return port;
  }
  throw new Error(`No free port found in range ${START_PORT}-${START_PORT + MAX_TRIES - 1}`);
}

async function main() {
  const port = await findPort();
  if (port !== START_PORT) {
    console.log(`⚠️   Port ${START_PORT} is in use — falling back to ${port}.`);
  }
  console.log(`🌐  Serving current directory on http://localhost:${port}\n`);

  // Pipe through to `npx serve` so the user sees its normal output.
  const child = spawn('npx', ['serve', '.', '--listen', String(port)], {
    stdio: 'inherit',
    shell: false,
  });
  child.on('exit', code => process.exit(code ?? 0));
}

main().catch(err => {
  console.error('❌  ' + err.message);
  process.exit(1);
});
